ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS access_level INTEGER NOT NULL DEFAULT 1 CHECK (access_level BETWEEN 0 AND 10);
-- AdoptaME / Antigravity — merchandising trazable  CREATE TABLE IF NOT EXISTS public.products (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   slug TEXT NOT NULL UNIQUE,   name TEXT NOT NULL,   description TEXT NOT NULL DEFAULT '',   price_cents INTEGER NOT NULL CHECK (price_cents > 0),   currency TEXT NOT NULL DEFAULT 'USD',   image_url TEXT,   inventory INTEGER NOT NULL DEFAULT 0 CHECK (inventory >= 0),   is_active BOOLEAN NOT NULL DEFAULT false,   created_at TIMESTAMPTZ NOT NULL DEFAULT now(),   updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );  CREATE TABLE IF NOT EXISTS public.product_variants (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   product_id UUID NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,   label TEXT NOT NULL,   sku TEXT UNIQUE,   price_delta_cents INTEGER NOT NULL DEFAULT 0,   inventory INTEGER NOT NULL DEFAULT 0 CHECK (inventory >= 0),   is_active BOOLEAN NOT NULL DEFAULT true,   UNIQUE(product_id, label) );  CREATE TABLE IF NOT EXISTS public.orders (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   order_number TEXT NOT NULL UNIQUE DEFAULT ('AME-' || upper(substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 10))),   customer_name TEXT NOT NULL,   customer_email TEXT NOT NULL,   customer_phone TEXT,   shipping_address JSONB,   status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'confirmed', 'paid', 'shipped', 'completed', 'cancelled')),   currency TEXT NOT NULL DEFAULT 'USD',   total_cents INTEGER NOT NULL DEFAULT 0 CHECK (total_cents >= 0),   idempotency_key TEXT UNIQUE,   payment_reference TEXT,   created_at TIMESTAMPTZ NOT NULL DEFAULT now(),   updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );  CREATE TABLE IF NOT EXISTS public.order_items (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,   product_id UUID NOT NULL REFERENCES public.products(id),   variant_id UUID REFERENCES public.product_variants(id),   product_name_snapshot TEXT NOT NULL,   variant_label_snapshot TEXT,   unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),   quantity INTEGER NOT NULL CHECK (quantity > 0),   UNIQUE(order_id, product_id, variant_id) );  CREATE TABLE IF NOT EXISTS public.order_status_history (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,   from_status TEXT,   to_status TEXT NOT NULL,   note TEXT,   changed_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,   created_at TIMESTAMPTZ NOT NULL DEFAULT now() );  ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY; ALTER TABLE public.order_status_history ENABLE ROW LEVEL SECURITY;  CREATE POLICY "products_public_read_active" ON public.products FOR SELECT TO anon, authenticated USING (is_active = true); CREATE POLICY "variants_public_read_active" ON public.product_variants FOR SELECT TO anon, authenticated USING (is_active = true); CREATE POLICY "orders_admin_read" ON public.orders FOR SELECT TO authenticated USING (public.has_access_level(4)); CREATE POLICY "orders_admin_update" ON public.orders FOR UPDATE TO authenticated USING (public.has_access_level(4)); CREATE POLICY "order_items_admin_read" ON public.order_items FOR SELECT TO authenticated USING (public.has_access_level(4)); CREATE POLICY "order_history_admin_read" ON public.order_status_history FOR SELECT TO authenticated USING (public.has_access_level(4)); -- AdoptaME / Antigravity — auditoría administrativa y seguimiento  CREATE TABLE IF NOT EXISTS public.audit_log (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   actor_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL,   entity_type TEXT NOT NULL,   entity_id UUID,   action TEXT NOT NULL CHECK (action IN ('create', 'update', 'delete', 'status_change', 'export')),   before_data JSONB,   after_data JSONB,   metadata JSONB NOT NULL DEFAULT '{}'::JSONB,   created_at TIMESTAMPTZ NOT NULL DEFAULT now() );  CREATE INDEX IF NOT EXISTS audit_log_entity_idx ON public.audit_log (entity_type, entity_id, created_at DESC); CREATE INDEX IF NOT EXISTS audit_log_actor_idx ON public.audit_log (actor_id, created_at DESC);  CREATE TABLE IF NOT EXISTS public.adoption_status_history (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   application_id UUID NOT NULL REFERENCES public.adoption_applications(id) ON DELETE CASCADE,   from_status TEXT,   to_status TEXT NOT NULL,   note TEXT,   changed_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,   created_at TIMESTAMPTZ NOT NULL DEFAULT now() );  CREATE INDEX IF NOT EXISTS adoption_status_history_application_idx   ON public.adoption_status_history (application_id, created_at DESC);  ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY; ALTER TABLE public.adoption_status_history ENABLE ROW LEVEL SECURITY;  CREATE POLICY "audit_admin_read" ON public.audit_log   FOR SELECT TO authenticated USING (public.has_access_level(7)); CREATE POLICY "adoption_history_admin_read" ON public.adoption_status_history   FOR SELECT TO authenticated USING (public.has_access_level(4));  CREATE OR REPLACE FUNCTION public.record_adoption_status_change() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN   IF OLD.status IS DISTINCT FROM NEW.status THEN     INSERT INTO public.adoption_status_history (application_id, from_status, to_status, changed_by)     VALUES (NEW.id, OLD.status, NEW.status, (SELECT auth.uid()));   END IF;   RETURN NEW; END; $$;  DROP TRIGGER IF EXISTS adoption_status_history_trigger ON public.adoption_applications; CREATE TRIGGER adoption_status_history_trigger   AFTER UPDATE OF status ON public.adoption_applications   FOR EACH ROW EXECUTE FUNCTION public.record_adoption_status_change();  REVOKE ALL ON FUNCTION public.record_adoption_status_change() FROM PUBLIC; -- AdoptaME / Antigravity — checkout público de merchandising en USD  CREATE OR REPLACE FUNCTION public.create_merchandise_order(   p_customer_name TEXT,   p_customer_email TEXT,   p_customer_phone TEXT,   p_product_slug TEXT,   p_quantity INTEGER DEFAULT 1,   p_idempotency_key TEXT DEFAULT NULL ) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$ DECLARE   v_product public.products%ROWTYPE;   v_order public.orders%ROWTYPE;   v_quantity INTEGER := COALESCE(p_quantity, 1); BEGIN   IF length(trim(COALESCE(p_customer_name, ''))) NOT BETWEEN 2 AND 120 THEN     RAISE EXCEPTION 'El nombre no es válido';   END IF;   IF lower(trim(COALESCE(p_customer_email, ''))) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN     RAISE EXCEPTION 'El correo no es válido';   END IF;   IF length(trim(COALESCE(p_customer_phone, ''))) NOT BETWEEN 7 AND 40 THEN     RAISE EXCEPTION 'El teléfono no es válido';   END IF;   IF v_quantity < 1 OR v_quantity > 20 THEN     RAISE EXCEPTION 'La cantidad debe estar entre 1 y 20';   END IF;    SELECT * INTO v_product   FROM public.products   WHERE slug = lower(trim(p_product_slug))     AND is_active = true     AND currency = 'USD'     AND inventory >= v_quantity   FOR UPDATE;    IF NOT FOUND THEN     RAISE EXCEPTION 'El producto no está disponible';   END IF;    IF p_idempotency_key IS NOT NULL THEN     SELECT * INTO v_order FROM public.orders WHERE idempotency_key = p_idempotency_key;     IF FOUND THEN       RETURN jsonb_build_object('id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status);     END IF;   END IF;    INSERT INTO public.orders (customer_name, customer_email, customer_phone, status, currency, total_cents, idempotency_key)   VALUES (trim(p_customer_name), lower(trim(p_customer_email)), trim(p_customer_phone), 'pending', 'USD', v_product.price_cents * v_quantity, p_idempotency_key)   RETURNING * INTO v_order;    INSERT INTO public.order_items (order_id, product_id, product_name_snapshot, unit_price_cents, quantity)   VALUES (v_order.id, v_product.id, v_product.name, v_product.price_cents, v_quantity);    UPDATE public.products   SET inventory = inventory - v_quantity, updated_at = now()   WHERE id = v_product.id;    RETURN jsonb_build_object('id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status); END; $$;  REVOKE ALL ON FUNCTION public.create_merchandise_order(TEXT, TEXT, TEXT, TEXT, INTEGER, TEXT) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_merchandise_order(TEXT, TEXT, TEXT, TEXT, INTEGER, TEXT) TO anon, authenticated;  CREATE OR REPLACE FUNCTION public.record_order_status_change() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$ BEGIN   IF TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN     INSERT INTO public.order_status_history (order_id, from_status, to_status, changed_by)     VALUES (NEW.id, CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.status END, NEW.status, auth.uid());   END IF;   RETURN NEW; END; $$;  DROP TRIGGER IF EXISTS orders_status_history_trigger ON public.orders; CREATE TRIGGER orders_status_history_trigger AFTER INSERT OR UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.record_order_status_change(); -- AdoptaME / Antigravity — normaliza acceso por rol  -- Corrige perfiles antiguos que tienen role='admin' pero conservaron el nivel 1 -- creado por el trigger inicial. No reduce niveles asignados manualmente. UPDATE public.profiles SET access_level = CASE role   WHEN 'super_admin' THEN GREATEST(access_level, 10)   WHEN 'admin' THEN GREATEST(access_level, 7)   WHEN 'editor' THEN GREATEST(access_level, 4)   ELSE access_level END, updated_at = now() WHERE role IN ('super_admin', 'admin', 'editor');  CREATE OR REPLACE FUNCTION public.has_access_level(required_level INTEGER) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$   SELECT EXISTS (     SELECT 1 FROM public.profiles     WHERE id = (SELECT auth.uid())       AND is_active = true       AND CASE role         WHEN 'super_admin' THEN GREATEST(access_level, 10)         WHEN 'admin' THEN GREATEST(access_level, 7)         WHEN 'editor' THEN GREATEST(access_level, 4)         ELSE access_level       END >= required_level   ); $$;  REVOKE ALL ON FUNCTION public.has_access_level(INTEGER) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_access_level(INTEGER) TO authenticated;
